import { describe, expect, test } from 'bun:test';
import { pluginSource } from './plugin-source';

/** The plugin with loaders, whole: what a reviewer reads to check Nuxt's context rules. */
const LAZY_PLUGIN = [
	'// Generated by @nxgt/i18n-vue/nuxt. Never edited.',
	"import { defineNuxtPlugin, useCookie, useHead, useRequestHeaders, useState } from '#imports';",
	"import { setupLazyNuxtI18n } from '@nxgt/i18n-vue/nuxt/runtime';",
	'',
	'const catalogues = {"en":{"home":{"title":"Welcome"}}};',
	'const loaders = {',
	'\t"fr": () => import("#build/nxgt-i18n-vue/locales/fr.mjs"),',
	'};',
	'const locales = ["en","fr"];',
	'',
	'export default defineNuxtPlugin({',
	"\tname: '@nxgt/i18n-vue',",
	"\tenforce: 'pre',",
	'\tasync setup(nuxtApp) {',
	"\t\t// Every composable before the first await: Nuxt's context is gone after it.",
	'\t\tconst header = import.meta.server',
	"\t\t\t? useRequestHeaders(['accept-language'])['accept-language']",
	'\t\t\t: undefined;',
	'\t\tconst i18n = await setupLazyNuxtI18n({',
	'\t\t\tcatalogues,',
	'\t\t\tloaders,',
	'\t\t\tlocales,',
	'\t\t\tfallbackLocale: "en",',
	`\t\t\tcookie: useCookie("lang", { path: '/', sameSite: 'lax', maxAge: 31536000 }),`,
	'\t\t\tstate: useState("@nxgt/i18n-vue:locale"),',
	'\t\t\tcatalogue: useState("@nxgt/i18n-vue:catalogue"),',
	'\t\t\trequested: () =>',
	'\t\t\t\timport.meta.server',
	'\t\t\t\t\t? header',
	"\t\t\t\t\t: typeof navigator === 'undefined' ? null : navigator.languages,",
	'\t\t});',
	'\t\tnuxtApp.vueApp.use(i18n);',
	'\t\t// After the await: a composable needs the context back.',
	'\t\tnuxtApp.runWithContext(() => useHead({ htmlAttrs: { lang: i18n.locale } }));',
	'\t},',
	'});',
	'',
].join('\n');

describe('pluginSource with loaders', () => {
	const source = pluginSource({
		catalogues: { en: { home: { title: 'Welcome' } } },
		fallbackLocale: 'en',
		cookie: 'lang',
		loaders: { fr: '#build/nxgt-i18n-vue/locales/fr.mjs' },
	});

	test('awaits setupLazyNuxtI18n, every composable before the await and useHead in runWithContext', () => {
		expect(source).toBe(LAZY_PLUGIN);
		const awaited = source.indexOf('await setupLazyNuxtI18n');
		expect(source.indexOf('useRequestHeaders(')).toBeLessThan(awaited);
		expect(source.indexOf('runWithContext(() => useHead(')).toBeGreaterThan(
			awaited,
		);
	});

	test('is not parallel, so Nuxt awaits it before rendering', () => {
		expect(source).not.toContain('parallel');
	});
});
